//! Text dumps for tests: ordered `key = value` lines compared exactly with a file, so a change in
//! generated styles or tokens shows up as a reviewable diff.
//!
//! Without `UPDATE_DUMPS`, a mismatch fails with the differing lines; with `UPDATE_DUMPS=1` the
//! file is rewritten. Dumps are generated by tests only, never edited by hand.
//!
//!
//! Values that differ between themes are written once with the common value and one `key@theme` line per theme that
//! differs ([`Themed`]). The dumps of the whole workspace stay under [`BUDGET`] lines ([`check_budget`]).

use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use crate::style::{ComponentStyle, StyleCx, StyleKey, UiTokens, Variant};
use crate::testing::style::{style_of, with_cx};
use craft_theme::{Contrast, ControlSize};
use egui::{Color32, CornerRadius, FontFamily, FontId, Margin, Rangef, Shadow, Stroke, Vec2};

/// Ordered `key = value` lines.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Dump {
    text: String,
    prefix: String,
}

impl Dump {
    /// An empty dump.
    pub fn new() -> Self {
        Self::default()
    }

    /// A `# text` line, e.g. naming the test that writes the file.
    pub fn comment(&mut self, text: &str) -> &mut Self {
        let _ = writeln!(self.text, "# {text}");
        self
    }

    /// Appends `key = value`, with `key` under the current [`group`](Self::group) prefix.
    pub fn line(&mut self, key: &str, value: impl DumpValue) -> &mut Self {
        let _ = writeln!(self.text, "{}{key} = {}", self.prefix, value.dump_value());
        self
    }

    /// Runs `f` with `prefix.` put before every key it writes.
    pub fn group(&mut self, prefix: &str, f: impl FnOnce(&mut Dump)) -> &mut Self {
        let len = self.prefix.len();
        let _ = write!(self.prefix, "{prefix}.");
        f(self);
        self.prefix.truncate(len);
        self
    }

    /// The lines written so far.
    pub fn text(&self) -> &str {
        &self.text
    }

    /// The `(key, value)` pairs written so far, keys with their group prefixes; comments are
    /// skipped.
    pub fn entries(&self) -> impl Iterator<Item = (String, &str)> {
        self.text.lines().filter(|line| !line.starts_with('#')).filter_map(|line| line.split_once(" = ")).map(|(key, value)| (key.to_owned(), value))
    }

    /// Compares with the file at `path`, or rewrites it when [`update_requested`]. The error
    /// names the file and lists the differing lines.
    pub fn compare(&self, path: impl AsRef<Path>) -> Result<(), String> {
        let path = path.as_ref();
        let old = std::fs::read_to_string(path);
        if update_requested() {
            if old.as_deref().ok() == Some(self.text.as_str()) {
                return Ok(());
            }
            if let Some(dir) = path.parent() {
                std::fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
            }
            return std::fs::write(path, &self.text).map_err(|e| format!("{}: {e}", path.display()));
        }
        match old {
            Ok(old) if old == self.text => Ok(()),
            Ok(old) => Err(format!("{} differs:\n{}", path.display(), diff(&old, &self.text))),
            Err(e) => Err(format!("{}: {e}", path.display())),
        }
    }

    /// [`compare`](Self::compare), failing the test on a mismatch.
    #[track_caller]
    #[allow(clippy::panic)] // a test assertion
    pub fn check(&self, path: impl AsRef<Path>) {
        if let Err(message) = self.compare(path) {
            panic!("{message}\nRerun with UPDATE_DUMPS=1 to rewrite the dump, then review the diff.");
        }
    }
}

/// Checks a directory one test owns: every `(file name, dump)` pair, and no other `.txt` files
/// (with `UPDATE_DUMPS=1` they are removed). Fails with the first three diffs.
#[track_caller]
#[allow(clippy::panic)] // a test assertion
pub fn check_dir(dir: impl AsRef<Path>, dumps: &[(String, Dump)]) {
    let dir = dir.as_ref();
    let names: BTreeSet<&str> = dumps.iter().map(|(name, _)| name.as_str()).collect();
    let stale: Vec<_> = std::fs::read_dir(dir)
        .into_iter()
        .flatten()
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|p| p.extension().is_some_and(|e| e == "txt"))
        .filter(|p| p.file_name().and_then(|n| n.to_str()).is_some_and(|n| !names.contains(n)))
        .collect();

    let mut errors: Vec<String> = dumps.iter().filter_map(|(name, dump)| dump.compare(dir.join(name)).err()).collect();
    for path in stale {
        if update_requested() {
            if let Err(e) = std::fs::remove_file(&path) {
                errors.push(format!("{}: {e}", path.display()));
            }
        } else {
            errors.push(format!("{}: no longer generated", path.display()));
        }
    }
    if !errors.is_empty() {
        let shown: Vec<&str> = errors.iter().take(3).map(String::as_str).collect();
        panic!("{} dump file(s) differ; rerun with UPDATE_DUMPS=1 to rewrite them, then review the diff\n{}", errors.len(), shown.join("\n"));
    }
}

/// Whether `UPDATE_DUMPS` is set (to anything but `0`).
pub fn update_requested() -> bool {
    std::env::var_os("UPDATE_DUMPS").is_some_and(|v| v != "0")
}

/// The lines only in `old` (`- `) and only in `new` (`+ `), at most 20. Dump keys are unique, so
/// this reads as a diff.
pub fn diff(old: &str, new: &str) -> String {
    const MAX: usize = 20;
    let (a, b): (BTreeSet<&str>, BTreeSet<&str>) = (old.lines().collect(), new.lines().collect());
    let removed = old.lines().filter(|l| !b.contains(l)).map(|l| format!("- {l}"));
    let added = new.lines().filter(|l| !a.contains(l)).map(|l| format!("+ {l}"));
    let all: Vec<String> = removed.chain(added).collect();
    let mut out: Vec<String> = all.iter().take(MAX).cloned().collect();
    if all.len() > MAX {
        out.push(format!("… {} more", all.len() - MAX));
    }
    out.join("\n")
}

/// A value's text in a dump.
pub trait DumpValue {
    /// The value as dump text.
    fn dump_value(&self) -> String;
}

impl<T: DumpValue + ?Sized> DumpValue for &T {
    fn dump_value(&self) -> String {
        (**self).dump_value()
    }
}

/// Up to two decimals, trailing zeros dropped: `12`, `10.5`, `0.33`.
impl DumpValue for f32 {
    fn dump_value(&self) -> String {
        let s = format!("{self:.2}");
        let s = s.trim_end_matches('0').trim_end_matches('.');
        if s == "-0" { "0".to_owned() } else { s.to_owned() }
    }
}

macro_rules! display_values {
    ($($t:ty),*) => { $(impl DumpValue for $t { fn dump_value(&self) -> String { self.to_string() } })* };
}
display_values!(bool, u8, u16, u32, u64, usize, i8, i16, i32, i64, str, String);

/// `none`, or the value.
impl<T: DumpValue> DumpValue for Option<T> {
    fn dump_value(&self) -> String {
        self.as_ref().map_or_else(|| "none".to_owned(), DumpValue::dump_value)
    }
}

/// `#rrggbbaa`, unmultiplied.
impl DumpValue for Color32 {
    fn dump_value(&self) -> String {
        let [r, g, b, a] = self.to_srgba_unmultiplied();
        format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
    }
}

/// `#rrggbbaa`.
impl DumpValue for craft_theme::Rgba {
    fn dump_value(&self) -> String {
        let [r, g, b, a] = self.0;
        format!("#{r:02x}{g:02x}{b:02x}{a:02x}")
    }
}

/// `x y`.
impl DumpValue for Vec2 {
    fn dump_value(&self) -> String {
        format!("{} {}", self.x.dump_value(), self.y.dump_value())
    }
}

/// `min..max`.
impl DumpValue for Rangef {
    fn dump_value(&self) -> String {
        format!("{}..{}", self.min.dump_value(), self.max.dump_value())
    }
}

/// `width colour`.
impl DumpValue for Stroke {
    fn dump_value(&self) -> String {
        format!("{} {}", self.width.dump_value(), self.color.dump_value())
    }
}

/// One number when all corners match, else `nw ne sw se`.
impl DumpValue for CornerRadius {
    fn dump_value(&self) -> String {
        let CornerRadius { nw, ne, sw, se } = *self;
        if nw == ne && ne == sw && sw == se { nw.to_string() } else { format!("{nw} {ne} {sw} {se}") }
    }
}

/// One number when all sides match, else `left right top bottom`.
impl DumpValue for Margin {
    fn dump_value(&self) -> String {
        let Margin { left, right, top, bottom } = *self;
        if left == right && right == top && top == bottom { left.to_string() } else { format!("{left} {right} {top} {bottom}") }
    }
}

/// `offset x y, blur b, spread s, colour`.
impl DumpValue for Shadow {
    fn dump_value(&self) -> String {
        let Shadow { offset: [x, y], blur, spread, color } = *self;
        format!("offset {x} {y}, blur {blur}, spread {spread}, {}", color.dump_value())
    }
}

/// `proportional`, `monospace` or the family's name.
impl DumpValue for FontFamily {
    fn dump_value(&self) -> String {
        match self {
            FontFamily::Proportional => "proportional".to_owned(),
            FontFamily::Monospace => "monospace".to_owned(),
            FontFamily::Name(name) => name.to_string(),
        }
    }
}

/// `size family`.
impl DumpValue for FontId {
    fn dump_value(&self) -> String {
        format!("{} {}", self.size.dump_value(), self.family.dump_value())
    }
}

/// The most lines the committed style dumps may hold in total.
pub const BUDGET: usize = 25_000;

/// The text a key's value takes in a theme that has no such key.
const ABSENT: &str = "<absent>";

/// The `(key, value)` lines of one theme, collected to be written with the other themes' (see [`Themed`]).
pub type Entries = Vec<(String, String)>;

/// Dump lines of one group in several themes, written as one line per key plus one per differing theme.
#[derive(Clone, Debug, Default)]
pub struct Themed {
    themes: Vec<(String, Entries)>,
}

impl Themed {
    /// No themes yet.
    pub fn new() -> Self {
        Self::default()
    }

    /// Adds the lines `entries` of theme `name`.
    pub fn theme(&mut self, name: &str, entries: Entries) -> &mut Self {
        self.themes.push((name.to_owned(), entries));
        self
    }

    /// Writes each key once, in first-seen order, with its most frequent value (the first of equals), then
    /// `key@theme = value` for each theme whose value differs or that lacks the key.
    pub fn write(&self, dump: &mut Dump) {
        let mut keys: Vec<&str> = Vec::new();
        for (_, entries) in &self.themes {
            for (key, _) in entries {
                if !keys.contains(&key.as_str()) {
                    keys.push(key);
                }
            }
        }
        for key in keys {
            let values: Vec<Option<&str>> =
                self.themes.iter().map(|(_, entries)| entries.iter().find(|(k, _)| k == key).map(|(_, v)| v.as_str())).collect();
            let mut best: Option<(&str, usize)> = None;
            for value in values.iter().flatten() {
                let count = values.iter().filter(|v| **v == Some(*value)).count();
                if best.is_none_or(|(_, most)| count > most) {
                    best = Some((value, count));
                }
            }
            let Some((common, _)) = best else { continue };
            dump.line(key, common);
            for ((theme, _), value) in self.themes.iter().zip(&values) {
                if *value != Some(common) {
                    dump.line(&format!("{key}@{theme}"), value.unwrap_or(ABSENT));
                }
            }
        }
    }
}

/// The fields of a value as `(path, text)` pairs, read from its pretty `Debug` form: a struct field is its name, a
/// tuple field or list item its index, joined by dots. A type with a `Debug` derive needs nothing more to be dumped.
pub fn flatten_debug(value: &dyn std::fmt::Debug) -> Entries {
    let text = format!("{value:#?}");
    let mut out = Entries::new();
    // One frame per open bracket: its path segment and the index its next unnamed child takes.
    let mut stack: Vec<(String, usize)> = vec![(String::new(), 0)];
    for (index, raw) in text.lines().enumerate() {
        let line = raw.trim().trim_end_matches(',');
        if matches!(line, "}" | ")" | "]") {
            stack.pop();
            continue;
        }
        let (name, rest) = match line.split_once(": ") {
            Some((name, rest)) if !name.is_empty() && name.chars().all(|c| c.is_alphanumeric() || c == '_') => (Some(name), rest),
            _ => (None, line),
        };
        let opens = rest.ends_with('{') || rest.ends_with('(') || rest.ends_with('[');
        if index == 0 {
            if opens {
                continue;
            }
            out.push(("value".to_owned(), rest.to_owned()));
            break;
        }
        let segment = match name {
            Some(name) => name.to_owned(),
            None => stack.last_mut().map_or_else(String::new, |(_, next)| {
                *next += 1;
                (*next - 1).to_string()
            }),
        };
        if opens {
            stack.push((segment, 0));
        } else {
            let mut parts: Vec<&str> = stack.iter().skip(1).map(|(s, _)| s.as_str()).collect();
            parts.push(&segment);
            out.push((parts.join("."), rest.to_owned()));
        }
    }
    out
}

/// Every built-in theme in each mode it has, at standard contrast, as (`<theme>.<mode>`, tokens).
pub fn themes() -> Vec<(String, UiTokens)> {
    super::style::themes_at(Contrast::Standard)
}

/// The resolved style of the component whose `style` function is `default`, for each of `variants` and in every
/// theme of [`themes`], written into `dump` under `<name>.<variant>`: each key once with its common value, plus
/// the themes that differ. The style comes from the style cache, as in a frame.
pub fn dump_style<K: StyleKey, S: ComponentStyle + std::fmt::Debug>(
    dump: &mut Dump,
    ctx: &egui::Context,
    name: &str,
    variants: &[Variant],
    size: ControlSize,
    key: K,
    default: for<'a> fn(&StyleCx<'a>, K) -> S,
) {
    let themes = themes();
    for &variant in variants {
        let mut themed = Themed::new();
        for (theme, tokens) in &themes {
            let style = with_cx(ctx, tokens, variant, size, |cx| style_of(ctx, cx, key, default));
            themed.theme(theme, flatten_debug(&*style));
        }
        let group = format!("{name}.{}", format!("{variant:?}").to_lowercase());
        dump.group(&group, |d| themed.write(d));
    }
}

/// What `resolve` reads from the tokens of every theme of [`themes`], written into `dump` under `name`: each key
/// once with its common value, plus the themes that differ.
pub fn dump_resolved<T: std::fmt::Debug>(dump: &mut Dump, name: &str, resolve: impl Fn(&UiTokens) -> T) {
    let mut themed = Themed::new();
    for (theme, tokens) in themes() {
        themed.theme(&theme, flatten_debug(&resolve(&tokens)));
    }
    dump.group(name, |d| themed.write(d));
}

/// The directories `crates/*/tests/dumps` of the workspace, without the crates in `skip`.
fn dump_dirs(skip: &[&str]) -> Vec<PathBuf> {
    let crates = Path::new(env!("CARGO_MANIFEST_DIR")).join("..");
    let mut dirs: Vec<PathBuf> = std::fs::read_dir(&crates)
        .into_iter()
        .flatten()
        .flatten()
        .filter(|entry| entry.file_name().to_str().is_some_and(|name| !skip.contains(&name)))
        .map(|entry| entry.path().join("tests").join("dumps"))
        .filter(|dir| dir.is_dir())
        .collect();
    dirs.sort();
    dirs
}

fn count_lines(dir: &Path) -> usize {
    let mut total = 0;
    for entry in std::fs::read_dir(dir).into_iter().flatten().flatten() {
        let path = entry.path();
        if path.is_dir() {
            total += count_lines(&path);
        } else if path.extension().is_some_and(|e| e == "txt") {
            total += std::fs::read_to_string(&path).map(|text| text.lines().filter(|l| !l.starts_with('#')).count()).unwrap_or(0);
        }
    }
    total
}

/// The lines of every dump file under `crates/*/tests/dumps` except those of the crates in `skip`, comments
/// left out. Token dumps stay in craft-theme and sit outside the budget.
pub fn dump_lines(skip: &[&str]) -> usize {
    dump_dirs(skip).iter().map(|dir| count_lines(dir)).sum()
}

/// Fails when the dumps outside `skip` hold more than [`BUDGET`] lines.
#[track_caller]
#[allow(clippy::panic)] // a test assertion
pub fn check_budget(skip: &[&str]) {
    let lines = dump_lines(skip);
    assert!(lines <= BUDGET, "the style dumps hold {lines} lines; the budget is {BUDGET}");
}
